<div class="section-heading"><div><p class="eyebrow">TRANSAKSI TOKO</p><h1>Kelola pesanan</h1><p class="text-muted mb-0"><?= $pager->getTotal() ?> pesanan ditemukan.</p></div></div><form class="form-panel report-filter mb-4" method="get"><div class="filter-grow"><label class="form-label" for="q">Cari pesanan</label><input class="form-control" id="q" name="q" value="<?= esc($q, 'attr') ?>" placeholder="Kode, nama, atau WhatsApp"></div><div><label class="form-label" for="status">Status</label><select class="form-select" id="status" name="status"><option value="">Semua status</option><?php foreach (['baru','diproses','dikirim','selesai','dibatalkan'] as $value): ?><option value="<?= $value ?>" <?= $selectedStatus === $value ? 'selected' : '' ?>><?= ucfirst($value) ?></option><?php endforeach ?></select></div><button class="btn btn-primary" type="submit">Cari</button></form><div class="table-responsive admin-table"><table class="table align-middle mb-0"><thead><tr><th>Kode</th><th>Pembeli</th><th>Tanggal</th><th>Total</th><th>Pembayaran</th><th>Status</th><th>Tindakan</th></tr></thead><tbody><?php foreach ($orders as $order): ?><tr><td><strong><?= esc($order['kode_order']) ?></strong></td><td><?= esc($order['nama_pembeli']) ?><br><small class="text-muted"><?= esc($order['whatsapp']) ?></small></td><td><?= date('d M Y H:i', strtotime($order['created_at'])) ?></td><td><?= rupiah($order['total']) ?></td><td><span class="status-pill"><?= $order['status_pembayaran'] === 'sudah_dibayar' ? 'Sudah dibayar' : 'Belum dibayar' ?></span></td><td><span class="status-pill status-<?= esc($order['status'], 'attr') ?>"><?= ucfirst(esc($order['status'])) ?></span></td><td><a class="btn btn-sm btn-outline-primary" href="<?= site_url('admin/pesanan/' . $order['id']) ?>">Detail</a></td></tr><?php endforeach ?><?php if (! $orders): ?><tr><td colspan="7" class="p-5 text-center">Pesanan tidak ditemukan.</td></tr><?php endif ?></tbody></table></div><?= $pager->links('default', 'shop') ?>
